SELECT jsonb_build_object('children',(SELECT jsonb_agg(to_jsonb(g)) FROM tb_agregadores g WHERE id_agregador_pai IN (57,60)),'nextEstacoes',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT e.id_evento,e.nome_evento,e.tag,e.data_inicial,e.estado,e.cidade,e.url_hotsite,(SELECT jsonb_agg(ge.agregador_tag) FROM tb_agregadores_eventos ge WHERE ge.id_evento=e.id_evento) AS memberships FROM tb_evento_corridas e WHERE e.ativo AND e.data_inicial>=current_date AND e.nome_evento ILIKE '%estações%' ORDER BY e.data_inicial LIMIT 30) x))::text payload
